#define MAXR 20
#define MAXC 20

typedef struct {
    int r, c, dir, mem;
} State;

int R, C;
char board[MAXR][MAXC + 1];
int visited[MAXR][MAXC][4][16];

int dr[4] = {0, 0, -1, 1};   // right, left, up, down
int dc[4] = {1, -1, 0, 0};

int wrap_r(int x) {
    if (x < 0) return R - 1;
    if (x >= R) return 0;
    return x;
}

int wrap_c(int x) {
    if (x < 0) return C - 1;
    if (x >= C) return 0;
    return x;
}

int dfs(int r, int c, int dir, int mem) {
    if (visited[r][c][dir][mem]) return 0;
    visited[r][c][dir][mem] = 1;

    char ch = board[r][c];
    if (ch == '@') return 1;

    int ndir = dir, nmem = mem;

    if (ch >= '0' && ch <= '9') {
        nmem = ch - '0';
    } else if (ch == '<') {
        ndir = 1;
    } else if (ch == '>') {
        ndir = 0;
    } else if (ch == '^') {
        ndir = 2;
    } else if (ch == 'v') {
        ndir = 3;
    } else if (ch == '_') {
        ndir = (mem == 0) ? 0 : 1;
    } else if (ch == '|') {
        ndir = (mem == 0) ? 3 : 2;
    } else if (ch == '+') {
        nmem = (mem + 1) % 16;
    } else if (ch == '-') {
        nmem = (mem + 15) % 16;
    }

    if (ch == '?') {
        for (int d = 0; d < 4; d++) {
            int nr = wrap_r(r + dr[d]);
            int nc = wrap_c(c + dc[d]);
            if (dfs(nr, nc, d, mem)) return 1;
        }
        return 0;
    } else {
        int nr = wrap_r(r + dr[ndir]);
        int nc = wrap_c(c + dc[ndir]);
        return dfs(nr, nc, ndir, nmem);
    }
}

int main() {
    int T;
    scanf("%d", &T);

