int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    // Directions: 0=up, 1=down, 2=left, 3=right
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    while (T--) {
        int R, C;
        cin >> R >> C;
        vector<string> board(R);
        for (int i = 0; i < R; ++i) cin >> board[i];

        // visited[r][c][dir][mem]
        static bool visited[20][20][4][16];
        memset(visited, 0, sizeof(visited));

        queue<State> q;
        q.push({0, 0, 3, 0}); // start at (0,0), moving right, memory=0
        visited[0][0][3][0] = true;

        bool canHalt = false;

        while (!q.empty() && !canHalt) {
            State cur = q.front();
            q.pop();

            char cmd = board[cur.r][cur.c];
            if (cmd == '@') {
                canHalt = true;
                break;
            }

            int mem = cur.mem;
            vector<int> nextDirs;

            if (cmd >= '0' && cmd <= '9') {
                mem = cmd - '0';
                nextDirs.push_back(cur.dir);
            } else if (cmd == '<') {
                nextDirs.push_back(2);
            } else if (cmd == '>') {
                nextDirs.push_back(3);
            } else if (cmd == '^') {
                nextDirs.push_back(0);
            } else if (cmd == 'v') {
                nextDirs.push_back(1);
            } else if (cmd == '_') {
                nextDirs.push_back(mem == 0 ? 3 : 2);
            } else if (cmd == '|') {
                nextDirs.push_back(mem == 0 ? 1 : 0);
            } else if (cmd == '?') {
                nextDirs = {0, 1, 2, 3};
            } else if (cmd == '+') {
                mem = (mem + 1) % 16;
                nextDirs.push_back(cur.dir);
            } else if (cmd == '-') {
                mem = (mem + 15) % 16;
                nextDirs.push_back(cur.dir);
            } else {
                // '.', '@' handled above, and any other command means continue straight
                nextDirs.push_back(cur.dir);
            }

            for (int ndir : nextDirs) {
                int nr = (cur.r + dr[ndir] + R) % R;
                int nc = (cur.c + dc[ndir] + C) % C;

                if (!visited[nr][nc][ndir][mem]) {
                    visited[nr][nc][ndir][mem] = true;
                    q.push({nr, nc, ndir, mem});
                }
            }
        }

        cout << (canHalt ? "YES" : "NO") << '\n';
    }

    return 0;
}

