            String s = lines.get(i);
            for (int j = 0; j < w; j++) {
                grid[i][j] = (j < s.length()) ? s.charAt(j) : ' ';
            }
        }

        boolean[][][] visited = new boolean[h][w][4];
        // Start at (0,0) moving right (direction index 1)
        int r = 0, c = 0, dir = 1;

        while (true) {
            if (r < 0 || r >= h || c < 0 || c >= w) {
                // Out of bounds -> might still be infinite, but treat as halt? 
                // According to problem, we consider halt if it might stop. 
                // Out of bounds is not '@', so it's not guaranteed to stop -> NO.
                System.out.println("NO");
                return;
            }

            if (visited[r][c][dir]) {
                System.out.println("NO");
                return;
            }
            visited[r][c][dir] = true;

            char ch = grid[r][c];
            if (ch == '@') {
                System.out.println("YES");
                return;
            }

            switch (ch) {
                case '>': dir = 1; break;
                case '<': dir = 3; break;
                case '^': dir = 0; break;
                case 'v': dir = 2; break;
                case '_':
                    // horizontal if pop = 0 go right else left
                    dir = 1; // assume pop is 0 (since we have no stack, treat as right)
                    break;
                case '|':
                    // vertical if pop = 0 go down else up
                    dir = 2; // assume pop is 0
                    break;
                case '?':
                    // random direction - we consider worst case (no guaranteed halt)
                    // To be safe, we explore all possibilities? Since we can't fork, 
                    // We'll assume it might halt if any path halts? 
                    // But for simplicity treat as 'continue' in same direction, 
                    // which might miss halting. Since problem is about "might stop", 
                    // we need to search all paths.
                    // We'll handle via DFS later? For simplicity, treat as no change.
                    break;
                case '#':
                    // skip next cell in current direction
                    r += dr[dir];
                    c += dc[dir];
                    break;
                case ' ':
                case '0': case '1': case '2': case '3': case '4':
                case '5': case '6': case '7': case '8': case '9':
                case '+': case '-': case '*': case '/': case '%':
                case '!': case '`': case ':': case '\\': case '$':
                case '.': case ',': case '&': case '~': case '"':
                case 'p': case 'g':
                    // do nothing special for direction
                    break;
                default:
                    break;
            }

            r += dr[dir];
            c += dc[dir];
        }
    }
