    static class State {
        int r, c, dir, mem;
        State(int r, int c, int dir, int mem) {
            this.r = r;
            this.c = c;
            this.dir = dir;
            this.mem = mem;
        }
    }

    static int wrapRow(int r) {
        if (r < 0) return R - 1;
        if (r >= R) return 0;
        return r;
    }

    static int wrapCol(int c) {
        if (c < 0) return C - 1;
        if (c >= C) return 0;
        return c;
    }

    static boolean canHalt() {
        visited = new boolean[R][C][4][16];
        Queue<State> q = new ArrayDeque<>();
        q.offer(new State(0, 0, 1, 0)); // start at (0,0), moving right, memory=0
        visited[0][0][1][0] = true;

        while (!q.isEmpty()) {
            State cur = q.poll();
            int r = cur.r, c = cur.c, dir = cur.dir, mem = cur.mem;
            char ch = board[r][c];

            if (ch == '@') return true;

            List<State> nextStates = new ArrayList<>(4);

            if (ch >= '0' && ch <= '9') {
                mem = ch - '0';
            } else {
                switch (ch) {
                    case '<': dir = 3; break;
                    case '>': dir = 1; break;
                    case '^': dir = 0; break;
                    case 'v': dir = 2; break;
                    case '_': dir = (mem == 0 ? 1 : 3); break;
                    case '|': dir = (mem == 0 ? 2 : 0); break;
                    case '+': mem = (mem + 1) % 16; break;
                    case '-': mem = (mem + 15) % 16; break;
                    case '?':
                        for (int nd = 0; nd < 4; nd++) {
                            int nr = wrapRow(r + dr[nd]);
                            int nc = wrapCol(c + dc[nd]);
                            if (!visited[nr][nc][nd][mem]) {
                                visited[nr][nc][nd][mem] = true;
                                q.offer(new State(nr, nc, nd, mem));
                            }
                        }
                        continue;
                }
            }

            int nr = wrapRow(r + dr[dir]);
            int nc = wrapCol(c + dc[dir]);
            if (!visited[nr][nc][dir][mem]) {
                visited[nr][nc][dir][mem] = true;
                q.offer(new State(nr, nc, dir, mem));
            }
        }

        return false;
    }

